const atrasado = function atrasado(ultimaOk, agora) {
  if (!ultimaOk) return false;
  const quando = Date.parse(ultimaOk);
  if (!Number.isFinite(quando)) return false;
  return agora - quando > ATRASO_MS;
};
const corpoUso = function corpoUso(linha, schoolId, execucaoId, ocorridoEm) {
