    p_school_id: schoolId,
    p_execucao_id: String(execucaoId),
    p_no: linha.no,
    p_indice: linha.indice,
    p_tipo: "chat",
    p_modelo: linha.modelo,
    p_tokens_entrada: linha.tokens_entrada,
    p_tokens_saida: linha.tokens_saida,
    p_segundos_audio: null,
    p_estimado: linha.estimado === true,
