    p_custo_usd: null,
  };
};
const diaLocal = function diaLocal(ms) {
  return new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/Sao_Paulo",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(new Date(ms));
};
const deveChecarToken = function deveChecarToken(ultimoDia, agora) {
  if (!ultimoDia) return true;
  return String(ultimoDia) !== diaLocal(agora);
};
const dentroDaJanela = function dentroDaJanela(startedAt, agora) {
  const quando = Date.parse(startedAt ?? "");
  if (!Number.isFinite(quando)) return false;
  return agora - quando <= JANELA_MS && quando <= agora + 60_000;
};
const visitar = function visitar(no, fn, visto, profundidade) {
  if (no === null || typeof no !== "object" || profundidade > 40 || visto.has(no)) return;
  visto.add(no);
  if (fn(no) === false) return;
  const lista = Array.isArray(no) ? no : Object.values(no);
  for (const valor of lista) visitar(valor, fn, visto, profundidade + 1);
};
const escolasDaExecucao = function escolasDaExecucao(execucao) {
  const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  const ids = new Set();
  visitar(execucao, (no) => {
    if (Array.isArray(no)) return;
    for (const chave of ["school_id", "p_school_id"]) {
      const valor = no[chave];
      if (typeof valor === "string" && uuid.test(valor)) ids.add(valor.toLowerCase());
    }
  }, new WeakSet(), 0);
  return [...ids];
};
const modeloDe = function modeloDe(nome, json, mapa) {
  const textoDeModelo = (valor) => {
    if (typeof valor !== "string") return "";
    const texto = valor.trim();
    if (!texto || texto.startsWith("=")) return "";
    return texto;
  };
  const doMapa = textoDeModelo(mapa?.[nome]);
  if (doMapa) return doMapa;
  for (const chave of ["model", "modelName", "model_name"]) {
    const texto = textoDeModelo(json[chave]);
    if (texto) return texto;
  }
  return "desconhecido";
};
const registroAgenteOk = function registroAgenteOk(runData, nome = "Registrar uso do agente") {
  const runs = runData?.[nome];
  if (!Array.isArray(runs)) return false;
  return runs.some((run) => run && run.executionStatus === "success" && !run.error);
};
const usoNumerico = function usoNumerico(uso) {
  if (!uso || typeof uso !== "object") return null;
  const entrada = uso.promptTokens ?? uso.input_tokens;
  const saida = uso.completionTokens ?? uso.output_tokens;
  if (!Number.isFinite(Number(entrada)) || !Number.isFinite(Number(saida))) return null;
  if (Number(entrada) < 0 || Number(saida) < 0) return null;
  return { entrada: Math.trunc(Number(entrada)), saida: Math.trunc(Number(saida)) };
};
const extrairUsos = function extrairUsos(execucao, { modelosPorNo: mapa = {}, agora = Date.now() } = {}) {
  const status = String(execucao?.status ?? "");
  if (!STATUS_LER.has(status)) return { linhas: [], alertas: [] };
  if (!dentroDaJanela(execucao?.startedAt, agora)) return { linhas: [], alertas: [] };
  const rd = execucao?.data?.resultData?.runData ?? {};
  const linhas = [];
  for (const [nome, runs] of Object.entries(rd)) {
    let indice = 0;
    for (const run of Array.isArray(runs) ? runs : []) {
      const achados = [];
      visitar(run?.data, (no) => {
        if (!no || Array.isArray(no)) return;
        if (no.tokenUsage || no.tokenUsageEstimate) {
          achados.push(no);
          return false;
        }
      }, new WeakSet(), 0);
      for (const json of achados) {
        const real = usoNumerico(json.tokenUsage);
        const estimado = usoNumerico(json.tokenUsageEstimate);
        const escolhido = real ?? estimado;
        if (!escolhido) continue;
        linhas.push({
          no: nome,
          indice,
          estimado: !real && !!estimado,
          tokens_entrada: escolhido.entrada,
          tokens_saida: escolhido.saida,
          modelo: modeloDe(nome, json, mapa),
        });
        indice += 1;
      }
    }
  }
  const descartar = new Set();
  if (registroAgenteOk(rd)) descartar.add("Modelo");
  if (registroAgenteOk(rd, "Registrar uso do teste")) descartar.add("Modelo do teste");
  const linhasFinais = descartar.size ? linhas.filter((linha) => !descartar.has(linha.no)) : linhas;
  if (!linhasFinais.length) return { linhas: [], alertas: [] };
  const escolas = escolasDaExecucao(execucao);
  if (escolas.length !== 1) {
    return {
      linhas: [],
      alertas: [{ codigo: escolas.length === 0 ? "sem_escola" : "escola_ambigua", execucao_id: String(execucao.id ?? "") }],
    };
  }
  return { linhas: linhasFinais, alertas: [], school_id: escolas[0] };
};
const fluxosAlvo = function fluxosAlvo(lista) {
  return (lista ?? []).filter((wf) => {
    const nome = String(wf?.name ?? "");
    return NOMES_FLUXO.includes(nome) || nome.startsWith(PREFIXO_TEMP);
  });
};
const hostBloqueado = function hostBloqueado(valor, nome = "N8N_BASE_URL") {
  const texto = String(valor ?? "").trim();
  if (texto === "") {
    throw new Error(`${nome} não definido. O coletor não tem endereço padrão.`);
  }
  if (!/^https?:\/\//.test(texto)) {
    throw new Error(`${nome} não é uma URL`);
  }
  const semBarra = texto.replace(/\/+$/, "");
  const host = semBarra.replace(/^https?:\/\//, "").split("/")[0].split("@").pop().split(":")[0].toLowerCase();
  const bloqueado = "escola_exemplo" + "emilia.com.br";
  if (host === bloqueado || host.endsWith("." + bloqueado)) {
    throw new Error(`${nome} recusado`);
  }
  return semBarra;
};
const tetoDePaginas = function tetoDePaginas(teto) {
  const n = Number(teto);
  if (Number.isFinite(n) && n > 0) return Math.trunc(n);
  return TETO_PAGINAS_EXECUCAO;
};
const lerPaginaExecucoes = function lerPaginaExecucoes(pagina, agora, numero, teto) {
  const limite = tetoDePaginas(teto);
  const data = pagina && Array.isArray(pagina.data) ? pagina.data : [];
  const ids = [];
  let fora = false;
  for (const item of data) {
    if (item == null || typeof item !== "object") continue;
    if (!dentroDaJanela(item.startedAt, agora)) {
      fora = true;
      continue;
    }
    if (!STATUS_LER.has(String(item.status ?? ""))) continue;
    if (item.id == null || item.id === "") continue;
    ids.push(String(item.id));
  }
  const cursor = pagina?.nextCursor ? String(pagina.nextCursor) : "";
  const coberta = fora || cursor === "";
  const incompleta = !coberta && numero >= limite;
  return {
    ids,
    cursor: coberta || incompleta ? "" : cursor,
    parar: coberta || incompleta,
    incompleta,
  };
};
const erroRedePassageiro = function erroRedePassageiro(erro) {
  const marcas = ["EAI_AGAIN", "ENOTFOUND", "ETIMEDOUT", "ECONNRESET", "socket hang up"];
  const partes = [];
  const visto = new Set();
  let atual = erro;
  for (let i = 0; atual != null && i < 4; i += 1) {
    if (typeof atual === "string") {
      partes.push(atual);
      break;
    }
    if (typeof atual !== "object") {
      partes.push(String(atual));
      break;
    }
    if (visto.has(atual)) break;
    visto.add(atual);
    if (atual.code != null) partes.push(String(atual.code));
    if (atual.message != null) partes.push(String(atual.message));
    atual = atual.cause;
  }
  const texto = partes.join("\n");
  return marcas.some((marca) => texto.includes(marca));
};
const repetirRede = async function repetirRede(fn, rede) {
  const esperas = rede && Array.isArray(rede.esperas) ? rede.esperas : [1000, 3000];
  const dormir = rede && typeof rede.dormir === "function"
    ? rede.dormir
    : (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const total = esperas.length + 1;
  let ultimo;
  for (let i = 0; i < total; i += 1) {
    try {
      return await fn();
    } catch (erro) {
      ultimo = erro;
      if (!erroRedePassageiro(erro) || i === total - 1) throw erro;
      await dormir(esperas[i]);
    }
  }
  throw ultimo;
};
const n8n = async function n8n(rota, rede) {
  const base = rede.base;
  const key = rede.key;
  const http = rede.http;
  return repetirRede(async () => {
    const res = await http({
      method: "GET",
      url: base + "/api/v1" + rota,
      headers: { "X-N8N-API-KEY": key, accept: "application/json" },
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    if (res.statusCode < 200 || res.statusCode >= 300) throw new Error("n8n " + res.statusCode + " em " + rota);
    return res.body;
  }, rede);
};
const listarExecucoesNaJanela = async function listarExecucoesNaJanela(workflowId, agora, rede, teto) {
  const limite = tetoDePaginas(teto);
  const ids = [];
  const vistos = new Set();
  let cursor = "";
  for (let numero = 1; numero <= limite; numero += 1) {
    let rota = "/executions?workflowId=" + encodeURIComponent(String(workflowId)) + "&limit=" + encodeURIComponent(String(LIMITE_PAGINA));
    if (cursor) rota += "&cursor=" + encodeURIComponent(cursor);
    const page = await n8n(rota, rede);
    const lida = lerPaginaExecucoes(page, agora, numero, limite);
    for (const id of lida.ids) {
      if (vistos.has(id)) continue;
      vistos.add(id);
      ids.push(id);
    }
    if (lida.parar) return { ids, incompleta: lida.incompleta };
