};
const modelosPorNo = function modelosPorNo(workflow) {
  const mapa = {};
  for (const no of workflow?.nodes ?? []) {
    const modelo = no.parameters?.model?.value ?? no.parameters?.model;
    if (typeof modelo === "string" && modelo.trim()) mapa[no.name] = modelo.trim();
  }
