const rpc = async function rpc(nome, corpo, rede) {
  const banco = rede.banco;
  const anon = rede.anon;
  const jwt = rede.jwt;
  const http = rede.http;
  return repetirRede(async () => {
    const res = await http({
      method: "POST",
      url: banco + "/rest/v1/rpc/" + nome,
      headers: {
        "content-type": "application/json",
        apikey: anon,
        authorization: "Bearer " + jwt,
      },
      body: corpo,
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    if (res.statusCode === 401) return { status: 401, body: null };
    const body = res.body == null || res.body === "" ? null : res.body;
    return { status: res.statusCode, body };
  }, rede);
};
const JANELA_MS = 86400000;
const ATRASO_MS = 3600000;
const LIMITE_PAGINA = 100;
const TETO_PAGINAS_EXECUCAO = 50;
const NOMES_FLUXO = ["Lili (escolas)","Enviar WhatsApp (WhatsApp API)","Resumo da memória (Lili)"];
const PREFIXO_TEMP = "TEMP bancada Lili";
const STATUS_LER = new Set(["success","error","crashed"]);
const CONTINGENCIA = "Desculpe, tive uma instabilidade aqui agora. Pode me mandar sua mensagem de novo?";

const coletar = async () => {
  const env = (typeof $env === "object" && $env) ? $env : {};
  const base = hostBloqueado(env.N8N_BASE_URL);
  const key = env.N8N_API_KEY;
  const banco = hostBloqueado(env.API_BANCO_URL, "API_BANCO_URL");
  const anon = env.API_BANCO_CHAVE;
  const jwt = env.API_BANCO_JWT;
  if (!key || !anon || !jwt) throw new Error("faltam N8N_API_KEY, API_BANCO_CHAVE ou API_BANCO_JWT");
  const dados = $getWorkflowStaticData("global");
  const agora = Date.now();
  const resumo = { linhas: 0, duplicadas: 0, alertas: [], sem_escola: 0 };
  const http = (opcoes) => this.helpers.httpRequest(opcoes);
  const redeN8n = { http, base, key };
  const redeRpc = { http, banco, anon, jwt };

  async function evento(nivel, mensagem, contexto) {
    const r = await rpc("lili_registrar_evento", {
      p_school_id: null,
      p_nivel: nivel,
      p_mensagem: mensagem,
      p_operacao: "coletor-custo",
      p_contexto: contexto ?? null,
    }, redeRpc);
    if (r.status === 401) {
      resumo.alertas.push("banco_401");
      throw new Error("banco respondeu 401");
    }
    return r;
  }

  if (atrasado(dados.ultima_ok, agora)) {
    await evento("aviso", "Coletor de custo atrasado mais de 1 hora.", { ultima_ok: dados.ultima_ok });
  }

  async function paginar(caminho) {
    const itens = [];
    let cursor = "";
    for (let i = 0; i < 20; i++) {
      const sep = caminho.includes("?") ? "&" : "?";
      const page = await n8n(caminho + sep + "limit=" + encodeURIComponent("100") + (cursor ? "&cursor=" + encodeURIComponent(cursor) : ""), redeN8n);
      const data = Array.isArray(page) ? page : (page.data ?? []);
      itens.push(...data);
      cursor = page.nextCursor || "";
      if (!cursor) break;
    }
    return itens;
  }

  const fluxos = fluxosAlvo(await paginar("/workflows"));
  if (!fluxos.some((wf) => wf.name === "Lili (escolas)")) throw new Error("não achei o fluxo Lili (escolas)");
  const defs = {};
  for (const wf of fluxos) defs[wf.id] = modelosPorNo(await n8n("/workflows/" + encodeURIComponent(wf.id), redeN8n));

  const ids = [];
  const vistos = new Set();
  let incompleta = false;
  for (const wf of fluxos) {
    const lista = await listarExecucoesNaJanela(wf.id, agora, redeN8n);
    if (lista.incompleta) incompleta = true;
    for (const id of lista.ids) {
      if (vistos.has(id)) continue;
      vistos.add(id);
      ids.push(id);
    }
  }
  if (incompleta) resumo.alertas.push("janela_incompleta");
  let banco401 = false;
  for (const id of ids) {
    const cheia = await n8n("/executions/" + encodeURIComponent(id) + "?includeData=" + encodeURIComponent("true"), redeN8n);
    const extraido = extrairUsos(cheia, { modelosPorNo: defs[cheia.workflowId] ?? {}, agora });
    for (const alerta of extraido.alertas ?? []) {
      resumo.sem_escola += 1;
      await evento("aviso", "Execução de IA sem uma escola só.", alerta);
    }
    for (const linha of extraido.linhas ?? []) {
      const corpo = corpoUso(linha, extraido.school_id, cheia.id, cheia.startedAt);
      const r = await rpc("lili_registrar_uso_ia", corpo, redeRpc);
      if (r.status === 401) { banco401 = true; break; }
      if (r.status >= 400) throw new Error("rpc lili_registrar_uso_ia " + r.status);
      if (r.body?.duplicado) resumo.duplicadas += 1;
      else resumo.linhas += 1;
    }
    if (banco401) break;
  }

  if (banco401) {
    await evento("erro", "Banco respondeu 401 no coletor. Contingência para a família: " + CONTINGENCIA, null);
  }

  if (deveChecarToken(dados.ultimo_token_dia, agora)) {
    const token = await rpc("lili_token_status", {}, redeRpc);
    if (token.status === 401) {
      await evento("erro", "Banco respondeu 401 ao ler o token. Contingência para a família: " + CONTINGENCIA, null);
    } else {
      dados.ultimo_token_dia = diaLocal(agora);
      if (token.body?.vence_em_ate_14_dias === true) {
        await evento("aviso", "Token lili_n8n vence em até 14 dias.", { dias_restantes: token.body.dias_restantes ?? null });
      }
    }
  }

  dados.ultima_ok = new Date(agora).toISOString();
  return [{ json: resumo }];
};

